  cd "$spec_dir"
  java ${TLC_JAVA_OPTS:-} -cp "$tlc_jar" tlc2.TLC \
    -cleanup \
    -workers "$workers" \
    -metadir "$run_dir" \
    -config "$cfg_file" \
    "$module"
) 2>&1 | tee "$log_file"
tlc_status=${PIPESTATUS[0]}
set -e

