    echo "error: Sumeragi TLC '$mode' unexpectedly passed" >&2
    exit 1
  fi
  if grep -Eq "Invariant .* is violated|Error: Invariant|Error: The invariant of .* is equal to FALSE|Temporal properties were violated" "$log_file"; then
    echo "[formal] Sumeragi TLC '$mode' produced the expected failure"
    exit 0
  fi
  echo "error: Sumeragi TLC '$mode' failed without the expected invariant violation" >&2
  exit "$tlc_status"
fi

if [[ "$tlc_status" -ne 0 ]]; then
  exit "$tlc_status"
fi

echo "[formal] Sumeragi TLC '$mode' check passed"
